import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || '/api';

const api = axios.create({ baseURL: API_URL, headers: { 'Content-Type': 'application/json' } });

api.interceptors.request.use(config => {
  let token = localStorage.getItem('token');
  if (!token && typeof sessionStorage !== 'undefined') {
    token = sessionStorage.getItem('token');
  }
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

api.interceptors.response.use(
  res => res,
  err => {
    // Sadece 401 (token süresi doldu) durumunda logout yap, 403 (permission denied) değil
    if (err.response?.status === 401) {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      sessionStorage.removeItem('token');
      sessionStorage.removeItem('user');
      window.dispatchEvent(new CustomEvent('auth:logout'));
    }
    return Promise.reject(err);
  }
);

export const authService = {
  login: (email, password) => api.post('/auth/login', { email, password }),
  demo: () => api.post('/auth/demo'),
  register: (data) => api.post('/auth/register', data),
  logout: () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    sessionStorage.removeItem('token');
    sessionStorage.removeItem('user');
  },
  getMe: () => api.get('/auth/me'),
  updateProfile: (data) => api.put('/auth/profile', data),
  changePassword: (currentPassword, newPassword) =>
    api.put('/auth/password', { current_password: currentPassword, new_password: newPassword }),
  getSettings: () => api.get('/auth/settings'),
  updateSettings: (settings) => api.put('/auth/settings', settings),
  updateFarm: (data) => api.put('/auth/farm', data),
  deleteAccount: () => api.delete('/auth/account'),
  forgotPassword: (email) => api.post('/auth/forgot-password', { email }),
};

