import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { notificationsService } from '../../services/api';
import { LogOut, Menu, Bell, Search, Check, CheckCheck } from 'lucide-react';
import toast from 'react-hot-toast';

export default function Header({ onMenuClick }) {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [unreadCount, setUnreadCount] = useState(0);
  const [notifications, setNotifications] = useState([]);
  const [showDropdown, setShowDropdown] = useState(false);
  const [loadingNotifs, setLoadingNotifs] = useState(false);
  const dropdownRef = useRef(null);

  useEffect(() => {
    let isMounted = true;
    const fetchUnread = async () => {
      try {
        const res = await notificationsService.unreadCount();
        if (isMounted) setUnreadCount(res.data?.unread_count || 0);
      } catch {
        // Silently fail if unauthorized or server down
      }
    };
    fetchUnread();
    const interval = setInterval(fetchUnread, 30000);
    return () => {
      isMounted = false;
      clearInterval(interval);
    };
  }, []);

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleToggleNotifications = async () => {
    const nextState = !showDropdown;
    setShowDropdown(nextState);
    if (nextState) {
      setLoadingNotifs(true);
      try {
        const res = await notificationsService.list({ limit: 8 });
        setNotifications(res.data?.data || []);
      } catch {
        toast.error('Bildirimler yüklenemedi');
      } finally {
        setLoadingNotifs(false);
      }
    }
  };

  const handleMarkAsRead = async (id, e) => {
    e.stopPropagation();
    try {
      await notificationsService.markAsRead(id);
      setNotifications(prev => prev.map(n => n.id === id ? { ...n, is_read: true } : n));
      setUnreadCount(prev => Math.max(0, prev - 1));
    } catch {
      toast.error('İşlem başarısız');
    }
  };

  const handleMarkAllRead = async () => {
    try {
      await notificationsService.markAllAsRead();
      setNotifications(prev => prev.map(n => ({ ...n, is_read: true })));
      setUnreadCount(0);
      toast.success('Tüm bildirimler okundu işaretlendi');
    } catch {
      toast.error('İşlem başarısız');
    }
  };

  const handleLogout = () => {
    logout();
    toast.success('Çıkış yapıldı');
    navigate('/login');
  };

  const initials = (user?.full_name || user?.fullName || 'K')
    .split(' ')
    .map(n => n[0])
    .join('')
    .toUpperCase()
    .slice(0, 2);

  return (
    <header 
      className="px-4 md:px-6 py-3 flex items-center justify-between" 
      style={{ 
        backgroundColor: 'var(--bg-card)', 
        borderBottom: '1px solid var(--border-light)',
        boxShadow: '0 1px 4px rgba(0,0,0,0.02)'
      }}
    >
      <div className="flex items-center gap-3">
        <button 
          onClick={onMenuClick} 
          className="p-2 rounded-xl transition-all lg:hidden hover:bg-gray-100 active:scale-95"
          style={{ color: 'var(--text-secondary)' }}
        >
          <Menu className="w-5 h-5" />
        </button>

        <div className="hidden sm:flex items-center gap-2 px-3 py-2 rounded-xl bg-gray-50 border border-gray-200 text-sm text-gray-400 w-64">
          <Search className="w-4 h-4" />
          <span>Ara... (Yakında)</span>
        </div>
      </div>

      <div className="flex items-center gap-2">
        {/* Notification Bell with Dropdown */}
        <div className="relative" ref={dropdownRef}>
          <button 
            onClick={handleToggleNotifications}
            className="relative p-2.5 rounded-xl transition-all hover:bg-gray-100 active:scale-95"
            style={{ color: 'var(--text-secondary)' }}
            title="Bildirimler"
          >
            <Bell className="w-5 h-5" />
            {unreadCount > 0 && (
              <span className="absolute top-1.5 right-1.5 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-[10px] font-bold text-white ring-2 ring-white">
                {unreadCount > 9 ? '9+' : unreadCount}
              </span>
            )}
          </button>

          {showDropdown && (
            <div className="absolute right-0 mt-2 w-80 sm:w-96 rounded-2xl bg-white shadow-2xl border border-gray-100 z-50 overflow-hidden animate-fade-in">
              <div className="p-4 border-b border-gray-100 flex items-center justify-between bg-gray-50/50">
                <div className="flex items-center gap-2">
                  <h4 className="font-bold text-gray-900 text-sm">Bildirimler</h4>
                  {unreadCount > 0 && (
                    <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-teal-100 text-teal-800">
                      {unreadCount} yeni
                    </span>
                  )}
                </div>
                {unreadCount > 0 && (
                  <button 
                    onClick={handleMarkAllRead}
                    className="text-xs text-teal-600 hover:text-teal-700 font-semibold flex items-center gap-1"
                  >
                    <CheckCheck className="w-3.5 h-3.5" /> Tümünü Okundu Say
                  </button>
                )}
              </div>

              <div className="max-h-80 overflow-y-auto divide-y divide-gray-50">
                {loadingNotifs ? (
                  <div className="p-6 text-center text-gray-400 text-sm">
                    <div className="w-6 h-6 border-2 border-teal-600 border-t-transparent rounded-full animate-spin mx-auto mb-2" />
                    Yükleniyor...
                  </div>
                ) : notifications.length === 0 ? (
                  <div className="p-8 text-center text-gray-400 text-sm">
                    <p className="text-2xl mb-1">🔔</p>
                    <p>Henüz bildiriminiz yok</p>
                  </div>
                ) : (
                  notifications.map(n => (
                    <div 
                      key={n.id} 
                      className={`p-3.5 transition-colors flex items-start gap-3 hover:bg-gray-50/80 ${!n.is_read ? 'bg-teal-50/20' : ''}`}
                    >
                      <div className={`w-2 h-2 rounded-full mt-1.5 flex-shrink-0 ${!n.is_read ? 'bg-teal-600 ring-2 ring-teal-200' : 'bg-transparent'}`} />
                      <div className="flex-1 min-w-0">
                        <p className={`text-xs ${!n.is_read ? 'font-bold text-gray-900' : 'font-medium text-gray-700'}`}>
                          {n.title || n.message}
                        </p>
                        {n.title && n.message && (
                          <p className="text-[11px] text-gray-500 mt-0.5 line-clamp-2">{n.message}</p>
                        )}
                        <p className="text-[10px] text-gray-400 mt-1">
                          {n.created_at ? new Date(n.created_at).toLocaleDateString('tr-TR', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : ''}
                        </p>
                      </div>
                      {!n.is_read && (
                        <button 
                          onClick={(e) => handleMarkAsRead(n.id, e)}
                          className="p-1 rounded text-gray-400 hover:text-teal-600 hover:bg-teal-50"
                          title="Okundu işaretle"
                        >
                          <Check className="w-3.5 h-3.5" />
                        </button>
                      )}
                    </div>
                  ))
                )}
              </div>
            </div>
          )}
        </div>

        <div className="flex items-center gap-3 ml-2 pl-3" style={{ borderLeft: '1px solid var(--border-light)' }}>
          <div 
            className="w-9 h-9 rounded-xl flex items-center justify-center text-sm font-bold text-white cursor-pointer"
            style={{ background: 'linear-gradient(135deg, #0d9488, #059669)' }}
            onClick={() => navigate('/settings')}
            title="Profil & Ayarlar"
          >
            {initials}
          </div>
          <div className="hidden md:block cursor-pointer" onClick={() => navigate('/settings')}>
            <p className="text-sm font-semibold hover:text-teal-700 transition-colors" style={{ color: 'var(--text)' }}>
              {user?.full_name || user?.fullName || 'Kullanıcı'}
            </p>
            <p className="text-xs" style={{ color: 'var(--text-muted)' }}>
              {user?.farm_name || 'Çiftlik'}
            </p>
          </div>
        </div>

        <button 
          onClick={handleLogout}
          className="ml-1 p-2.5 rounded-xl transition-all hover:bg-red-50 hover:text-red-600 active:scale-95"
          style={{ color: 'var(--text-secondary)' }}
          title="Çıkış Yap"
        >
          <LogOut className="w-5 h-5" />
        </button>
      </div>
    </header>
  );
}
