import React from 'react';
import { NavLink } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { 
  LayoutDashboard, 
  PawPrint, 
  Stethoscope, 
  Droplets, 
  Baby, 
  Wallet, 
  Package, 
  ClipboardList, 
  BarChart3, 
  Settings,
  ShieldCheck
} from 'lucide-react';

const navItems = [
  { to: '/dashboard', label: 'Dashboard', icon: LayoutDashboard },
  { to: '/animals', label: 'Hayvanlar', icon: PawPrint },
  { to: '/health', label: 'Sağlık', icon: Stethoscope },
  { to: '/milk', label: 'Süt Üretimi', icon: Droplets },
  { to: '/reproduction', label: 'Üreme', icon: Baby },
  { to: '/finance', label: 'Finans', icon: Wallet },
  { to: '/inventory', label: 'Envanter', icon: Package },
  { to: '/tasks', label: 'Görevler', icon: ClipboardList },
  { to: '/reports', label: 'Raporlar', icon: BarChart3 },
  { to: '/settings', label: 'Ayarlar', icon: Settings },
];

export default function Sidebar({ open, onClose }) {
  const { user } = useAuth();

  const isAdmin = user && user.role === 'admin';
  const visibleItems = isAdmin 
    ? [...navItems.slice(0, 9), { to: '/admin', label: 'Admin Paneli', icon: ShieldCheck }, navItems[9]]
    : navItems;

  return (
    <>
      {open && (
        <div 
          className="fixed inset-0 bg-black/30 backdrop-blur-sm z-40 lg:hidden transition-opacity duration-300" 
          onClick={onClose} 
        />
      )}

      <aside className={`
        fixed inset-y-0 left-0 z-50
        lg:static lg:translate-x-0
        flex flex-col text-white
        transform transition-all duration-300 ease-in-out
        ${open ? 'translate-x-0 w-72' : '-translate-x-full w-72 lg:w-20'}
      `}
      style={{ 
        background: 'linear-gradient(180deg, #0d9488 0%, #0f766e 50%, #0d6b5e 100%)',
        boxShadow: open ? '4px 0 30px rgba(13, 148, 136, 0.3)' : 'none'
      }}>
        <div className="flex items-center gap-3 px-4 py-6" style={{ borderBottom: '1px solid rgba(255, 255, 255, 0.08)' }}>
          <div className="bg-white/95 p-1.5 rounded-xl shadow-lg">
            <img src="/mFk.png" alt="Logo" className="w-10 h-8 object-contain mfk-logo" />
          </div>
          {open && (
            <div className="overflow-hidden whitespace-nowrap">
              <span className="font-bold text-lg block leading-none tracking-tight">mFk Farm</span>
              <span className="text-[10px] text-teal-200 uppercase tracking-[0.15em] font-semibold">Management</span>
            </div>
          )}
        </div>

        <nav className="flex-1 py-4 overflow-y-auto px-2.5 space-y-0.5 scrollbar-thin">
          {visibleItems.map(item => (
            <NavLink
              key={item.to}
              to={item.to}
              onClick={() => window.innerWidth < 1024 && onClose()}
              className={({ isActive }) =>
                `sidebar-link ${isActive ? 'active' : ''}`
              }
            >
              <item.icon className="w-5 h-5 flex-shrink-0" />
              {open && <span>{item.label}</span>}
              {!open && <span className="lg:hidden">{item.label}</span>}
            </NavLink>
          ))}
        </nav>

        <div className="p-4 mt-auto" style={{ borderTop: '1px solid rgba(255, 255, 255, 0.08)' }}>
          {open ? (
            <div className="bg-white/5 backdrop-blur-sm rounded-xl p-3">
              <p className="text-[10px] text-teal-200 uppercase font-bold mb-1 tracking-wider">Versiyon</p>
              <p className="text-xs text-white/80 font-medium">v1.0.2 Stable</p>
            </div>
          ) : (
            <div className="text-center">
              <span className="text-[10px] font-bold text-white/60">v1.0</span>
            </div>
          )}
        </div>
      </aside>
    </>
  );
}
